// Fixed (hard-coded) messages — owner requirement. Sent verbatim; never generated by an LLM at runtime.
// Translations are produced once at compile time (agent-compile) and stored per agent.

export const FIXED = {
  orchestrator_off_topic: "Sorry, I can't help with that. I can only help you set up and improve your BuildStart agent.",
  agent_off_topic: "Sorry, I can't help with that. I can only help with questions about {{business_name}}.",
  validation_fallback: "Let me double-check that with the team and get back to you shortly.",
  handoff_owner_alert:
    "🙋 *Customer wants to talk to a person*\nFrom: {{customer_name_or_number}} ({{customer_number}})\nVia: {{channel}} · {{agent_name}}\nReason: {{reason}}\n{{summary_line}}Reply: https://wa.me/{{customer_digits}}\n— BuildStart",
  handoff_caller_line: "I've let the team know — someone will contact you on this number shortly.",
  handoff_chat_line: "I've let the team know — someone will reply to you here shortly.",
  dnc_confirmation: "Understood — we won't contact you again. Sorry for the trouble.",
  handoff_test: "✅ BuildStart test alert: handoff alerts for {{agent_name}} will arrive on this number.",
} as const;

export type FixedKey = keyof typeof FIXED;

export function fill(template: string, vars: Record<string, string | undefined | null>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? "");
}
